from pwn import *

def scan_ports():
    target = "chatterbox.chal.csaw.io"
    start_port = 1300
    end_port = 1399

    for port in range(start_port, end_port + 1):
        try:
            conn = remote(target, port, timeout=2)
            response = conn.recvline(timeout=2)
            print(f"[+] Port {port} is open. Response: {response}")
            conn.close()
            return port, response
        except Exception as e:
            pass

    return None, None

if __name__ == "__main__":
    active_port, response = scan_ports()

    if active_port:
        print(f"[ACTIVE] Server is live on port {active_port}. Initial response: {response}")
    else:
        print("No active ports found in the specified range.")
